/// The operations of this module.
pub fn routes() -> OpenApiRouter<AppState> {
    OpenApiRouter::new()
        .routes(routes!(list_contact_important_dates, create_contact_important_date))
        .routes(routes!(update_contact_important_date, delete_contact_important_date))
        .routes(routes!(list_contact_goals, create_contact_goal))
        .routes(routes!(get_contact_goal, update_contact_goal, delete_contact_goal))
        .routes(routes!(set_contact_goal_streak, delete_contact_goal_streak))
        .routes(routes!(list_contact_labels))
        .routes(routes!(assign_contact_label, unassign_contact_label))
        .routes(routes!(list_contact_reminders, create_contact_reminder))
        .routes(routes!(update_contact_reminder, delete_contact_reminder))
        .routes(routes!(list_contact_addresses, create_contact_address))
        .routes(routes!(update_contact_address, delete_contact_address))
        .routes(routes!(list_contact_information, create_contact_information))
        .routes(routes!(update_contact_information, delete_contact_information))
        .routes(routes!(list_contact_loans, create_contact_loan))
        .routes(routes!(update_contact_loan, delete_contact_loan))
        .routes(routes!(set_contact_job_information, delete_contact_job_information))
        .routes(routes!(set_contact_religion))
}
